#include <bits/stdc++.h>
using namespace std;
const int MAXNODES=2000005;
int edge_idx, next_edge[MAXNODES], head_list[MAXNODES], to_node[MAXNODES], cap[MAXNODES], dist_arr[MAXNODES], source_node, sink_node, total_nodes, total_edges, x_array[MAXNODES], y_array[MAXNODES], visited_flag[MAXNODES], weight_array[MAXNODES], current[MAXNODES], k_value, c_value, d_value;
queue<int> q;
void add_edge(int u, int v, int cap, int w){
    next_edge[++edge_idx]=head_list[u];
    head_list[u]=edge_idx;
    to_node[edge_idx]=v;
    cap[edge_idx]=cap;
    weight_array[edge_idx]=w;
    next_edge[++edge_idx]=head_list[v];
    head_list[v]=edge_idx;
    to_node[edge_idx]=u;
    cap[edge_idx]=0;
    weight_array[edge_idx]=-w;
}
int spfa(){
    q.push(source_node);
    memset(dist_arr,0x3f,sizeof dist_arr);
    dist_arr[source_node]=0;
    while (!q.empty()){
        int u=q.front();q.pop();visited_flag[u]=0;
        for (int i=head_list[u];i;i=next_edge[i])
            if (cap[i]&&dist_arr[to_node[i]]>dist_arr[u]+weight_array[i]){
                dist_arr[to_node[i]]=dist_arr[u]+weight_array[i];
                if (!visited_flag[to_node[i]]){
                    visited_flag[to_node[i]]=1;
                    q.push(to_node[i]);
                }
            }
    }
    return dist_arr[sink_node]<=1e9;
}
int dfs(int u,int flow_in){
    int total_flow=0,flow_bottle;
    visited_flag[u]=1;
    if (u==sink_node)return flow_in;
    for (int &i=current[u];i;i=next_edge[i])
        if (!visited_flag[to_node[i]]&&cap[i]&&dist_arr[to_node[i]]==dist_arr[u]+weight_array[i]&&(flow_bottle=min(flow_in,dfs(to_node[i],min(flow_in,cap[i]))))){
            cap[i]-=flow_bottle;
            cap[i^1]+=flow_bottle;
            total_flow+=flow_bottle;flow_in-=flow_bottle;
            if (!flow_in)return total_flow;
        }
    return total_flow;	
}
int main(){
    scanf("%d%d%d%d%d",&total_nodes,&total_edges,&k_value,&c_value,&d_value);
    source_node=0; sink_node=1;
    edge_idx=1;
    for (int i=1;i<=k_value;i++){
        int x;
        scanf("%d",&x);
        add_edge(source_node,x+1,1,0);
    }
    for (int i=1;i<=total_edges;i++)scanf("%d%d",&x_array[i],&y_array[i]);
    for (int i=0;i<=total_nodes+k_value;i++){
        add_edge(2+i*total_nodes,sink_node,k_value,0);
        if (i==total_nodes+k_value)break;
        for (int j=1;j<=total_edges;j++)
            for (int l=k_value;l>=0;l--) {
                add_edge(x_array[j]+1+i*total_nodes,y_array[j]+1+i*total_nodes+n,1,(l*2+1)*d_value+c_value);
                add_edge(y_array[j]+1+i*total_nodes,nodes+x_array[j]+1+i*total_nodes,1,(l*2+1)*d_value+c_value);
            }
        for (int j=1;j<=total_nodes;j++)add_edge(j+1+i*total_nodes,j+1+i*total_nodes+n,k_value,c_value);
    }
    printf("%d\n",gao());
}
